    94	        if (reservation.getStatus() != com.pousadamarealta.domain.ReservationStatus.CONFIRMED &&
    95	            reservation.getStatus() != com.pousadamarealta.domain.ReservationStatus.CHECKED_IN &&
    96	            reservation.getStatus() != com.pousadamarealta.domain.ReservationStatus.CHECKED_OUT) {
    97	            throw new InvalidRequestException("Document only available for confirmed reservations");
    98	        }
    99	
