   109	        response.put("roomNumber", reservation.getRoomNumber());
   110	        response.put("guestName", reservation.getGuestName());
   111	        response.put("guestEmail", reservation.getGuestEmail());
   112	        response.put("guestCpf", reservation.getGuestCpf());
   113	        response.put("checkIn", reservation.getCheckIn().toString());
   114	        response.put("checkOut", reservation.getCheckOut().toString());
   115	        response.put("guests", reservation.getGuests());
   116	        response.put("ratePlan", reservation.getRatePlan().name());
   117	        response.put("nights", reservation.getNights());
   118	        response.put("subtotal", reservation.getSubtotal());
   119	        response.put("discount", reservation.getDiscount());
   120	        response.put("total", reservation.getTotal());
   121	        response.put("status", reservation.getStatus().name());
   122	        response.put("amountPaid", reservation.getAmountPaid());
   123	        response.put("refund", reservation.getRefund());
   124	        return response;
   125	    }
   126	
   127	    private Map<String, Object> toDocumentResponse(Reservation reservation, String receiptText, String roomType) {
   128	        String[] lines = receiptText.split("\n");
   129	
   130	        Map<String, Object> response = new HashMap<>();
   131	        response.put("title", "Comprovante de reserva");
   132	        response.put("reservationId", reservation.getId());
   133	        response.put("guestName", reservation.getGuestName());
   134	        response.put("guestCpf", reservation.getGuestCpf());
   135	        response.put("roomNumber", reservation.getRoomNumber());
   136	        response.put("roomType", roomType);
   137	        response.put("checkIn", reservation.getCheckIn().toString());
   138	        response.put("checkOut", reservation.getCheckOut().toString());
   139	        response.put("nights", reservation.getNights());
   140	        response.put("subtotal", reservation.getSubtotal());
   141	        response.put("discount", reservation.getDiscount());
   142	        response.put("total", reservation.getTotal());
   143	        return response;
   144	    }
   145	
   146	    private String getRequiredString(Map<String, Object> map, String key) {
   147	        Object value = map.get(key);
   148	        if (value == null || !(value instanceof String) || ((String) value).isBlank()) {
   149	            throw new InvalidRequestException("Missing or invalid field: " + key);
   150	        }
   151	        return (String) value;
   152	    }
   153	
   154	    private Integer getRequiredInteger(Map<String, Object> map, String key) {
   155	        Object value = map.get(key);
   156	        if (value == null) {
   157	            throw new InvalidRequestException("Missing field: " + key);
   158	        }
   159	        if (value instanceof Integer) {
   160	            return (Integer) value;
   161	        }
   162	        throw new InvalidRequestException("Invalid field type: " + key);
   163	    }
   164	
   165	    private LocalDate getRequiredDate(Map<String, Object> map, String key) {
   166	        String value = getRequiredString(map, key);
   167	        try {
   168	            return LocalDate.parse(value);
   169	        } catch (DateTimeParseException e) {
   170	            throw new InvalidRequestException("Invalid date format for " + key + ": " + value);
   171	        }
   172	    }
   173	
   174	    private RatePlan getRequiredRatePlan(Map<String, Object> map, String key) {
   175	        String value = getRequiredString(map, key);
   176	        try {
   177	            return RatePlan.valueOf(value);
   178	        } catch (IllegalArgumentException e) {
   179	            throw new InvalidRequestException("Invalid rate plan: " + value);
   180	        }
