    52	        receipt.append("Hóspede: ").append(reservation.getGuestName())
    53	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    54	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
    55	               .append(" (").append(roomType).append(")\n");
    56	        receipt.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
    57	               .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
    58	               .append(" | ").append(nightsText).append("\n");
    59	        receipt.append("Diárias: ").append(currencyFormat.format(reservation.getSubtotal())).append("\n");
    60	
    61	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    62	            receipt.append("Desconto: ").append(currencyFormat.format(reservation.getDiscount())).append("\n");
    63	        }
    64	
    65	        receipt.append("Total: ").append(currencyFormat.format(reservation.getTotal()));
    66	
    67	        return receipt.toString();
    68	    }
