    70	    private String formatCpf(String cpf) {
    71	        if (cpf == null || cpf.length() != 11) {
    72	            return cpf;
    73	        }
    74	        return String.format("%s.%s.%s-%s",
    75	            cpf.substring(0, 3),
    76	            cpf.substring(3, 6),
    77	            cpf.substring(6, 9),
    78	            cpf.substring(9, 11));
    79	    }
