    28	
    29	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    30	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    31	                                        int guests, RatePlan ratePlan, String companyCode) {
    32	
    33	        Room room = roomRepository.findByNumber(roomNumber)
    34	            .orElseThrow(() -> new RoomNotFoundException(roomNumber));
    35	
    36	        if (guests < 1) {
    37	            throw new InvalidRequestException("Number of guests must be at least 1");
    38	        }
    39	
    40	        if (guests > room.getCapacity()) {
    41	            throw new CapacityExceededException(guests, room.getCapacity());
    42	        }
    43	
    44	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    45	            throw new InvalidRequestException("Check-out date must be after check-in date");
    46	        }
    47	
    48	        RatePlanStrategy strategy = RatePlanRegistry.get(ratePlan);
    49	        strategy.validate(room, checkIn, checkOut, guests, companyCode);
    50	
    51	        List<Reservation> conflicting = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
    52	        if (!conflicting.isEmpty()) {
    53	            throw new RoomUnavailableException(roomNumber);
    54	        }
    55	
    56	        PricingResult pricing;
    57	        if (ratePlan == RatePlan.CORPORATE && strategy instanceof CorporateRatePlan corporateStrategy) {
    58	            pricing = corporateStrategy.calculatePriceWithCompanyCode(room, checkIn, checkOut, companyCode);
    59	        } else {
    60	            pricing = strategy.calculatePrice(room, checkIn, checkOut);
    61	        }
    62	
    63	        Reservation reservation = new Reservation();
    64	        reservation.setRoomNumber(roomNumber);
    65	        reservation.setGuestName(guestName);
    66	        reservation.setGuestEmail(guestEmail);
    67	        reservation.setGuestCpf(guestCpf);
    68	        reservation.setCheckIn(checkIn);
    69	        reservation.setCheckOut(checkOut);
    70	        reservation.setGuests(guests);
    71	        reservation.setRatePlan(ratePlan);
    72	        reservation.setCompanyCode(companyCode);
    73	        reservation.calculateNights();
    74	        reservation.setSubtotal(pricing.getSubtotal());
    75	        reservation.setDiscount(pricing.getDiscount());
    76	        reservation.setTotal(pricing.getTotal());
    77	
    78	        return reservationRepository.save(reservation);
    79	    }
