   103	
   104	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   105	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   106	            throw new OperationNotAllowedException("Only pending or confirmed reservations can be cancelled");
   107	        }
   108	
   109	        RatePlanStrategy strategy = RatePlanRegistry.get(reservation.getRatePlan());
   110	        java.math.BigDecimal refundAmount = strategy.calculateRefund(reservation.getAmountPaid());
   111	
   112	        reservation.setStatus(ReservationStatus.CANCELLED);
   113	        reservation.setRefund(refundAmount);
   114	        reservationRepository.update(reservation);
   115	
   116	        return reservation;
   117	    }
